def rule(ctx):
    # Lower utilization = less of the maintenance budget used so far.
    def utilization(r):
        t = ctx.types[r.type]
        if t is None or t['continue_max_work'] <= 0:
            return 0.0
        return (t['continue_max_work'] - r.budget) / t['continue_max_work']

    # Prefer robots without a first maintenance yet, then lowest utilization,
    # then fewest duties, then earliest ready time.
    ordered = sorted(
        ctx.available,
        key=lambda r: (r.first_maint is not None, utilization(r), r.count, r.ready)
    )
    actions = [("reuse", r) for r in ordered]

    # If existing capacity cannot cover the remaining horizon, open a new robot proactively.
    need_new = ctx.capacity < ctx.remaining

    if need_new:
        best_k = None

        # Prefer the genome's type if it is still allowed and fits in the remaining time.
        if ctx.left[ctx.gene_type] > 0:
            t = ctx.types[ctx.gene_type]
            if t is not None and t['work_time'] <= ctx.remaining:
                best_k = ctx.gene_type

        if best_k is None:
            best_score = -1.0
            for k in range(len(ctx.types)):
                if ctx.left[k] > 0 and ctx.types[k] is not None:
                    t = ctx.types[k]
                    if t['work_time'] <= ctx.remaining:
                        # Total duty hours this robot can supply before maintenance.
                        duties = t['continue_max_work'] / max(1, t['single_work_time'])
                        score = duties * t['work_time']
                        if score > best_score:
                            best_score = score
                            best_k = k

        if best_k is None:
            for k in range(len(ctx.types)):
                if ctx.left[k] > 0:
                    best_k = k
                    break

        if best_k is not None:
            actions.insert(0, ("new", best_k))

    # Always keep a new-robot option at the end for deviation slots / fallback.
    if ctx.left[ctx.gene_type] > 0:
        if not (actions and actions[0][0] == "new" and actions[0][1] == ctx.gene_type):
            actions.append(("new", ctx.gene_type))
    else:
        for k in range(len(ctx.types)):
            if ctx.left[k] > 0:
                actions.append(("new", k))
                break

    return actions

