def rule(ctx):
    actions = []
    avail = ctx.available
    if avail:
        # Average work_time of all valid robot types, used to normalize the
        # trade-off between duty hours and duty counts.
        wts = [t['work_time'] for t in ctx.types if t is not None]
        avg_wt = sum(wts) / len(wts) if wts else 10.0

        def reuse_key(r):
            # Balance duty hours (primary when work_times differ) and duty counts.
            # With equal work_times this becomes pure count ordering (same as default).
            return (r.hours + 0.5 * r.count * avg_wt, r.count, r.idx)

        actions = [("reuse", r) for r in sorted(avail, key=reuse_key)]

    # New robot type preferences
    valid = []
    for k in range(len(ctx.types)):
        t = ctx.types[k]
        if t is not None and ctx.left[k] > 0:
            valid.append(k)
    if not valid:
        return actions

    def new_key(k):
        t = ctx.types[k]
        wt = t['work_time']
        overhead = t['out_travel_time'] + t['return_travel_time'] + t['charge_time']
        maint_term = t['maintenance_time'] / t['continue_max_work'] if t['continue_max_work'] > 0 else 0.0
        score = overhead / wt + maint_term
        if wt <= ctx.remaining:
            # Fitting types: prefer larger work_time (fewer shifts), then efficiency.
            return (0, -wt, score, -ctx.left[k], k)
        else:
            # Non-fitting: prefer smaller work_time to fit, then efficiency.
            return (1, wt, score, -ctx.left[k], k)

    valid.sort(key=new_key)
    if ctx.gene_type in valid:
        valid.remove(ctx.gene_type)
        valid.insert(0, ctx.gene_type)

    actions.extend(("new", k) for k in valid)
    return actions

