def rule(ctx):
    actions = []
    # Use the pre-sorted available robots (count asc, budget desc).
    # This balances duty counts and duty hours across all robots.
    for r in ctx.available:
        actions.append(("reuse", r))

    # Determine which robot types can still be opened.
    valid = []
    for k in range(len(ctx.types)):
        t = ctx.types[k]
        if t is not None and ctx.left[k] > 0:
            valid.append(k)

    if not valid:
        return actions

    R = ctx.remaining

    def new_key(k):
        t = ctx.types[k]
        wt = t['work_time']
        overhead = t['out_travel_time'] + t['return_travel_time'] + t['charge_time']
        single = t['single_work_time']
        cont = t['continue_max_work']
        maint = t['maintenance_time']
        # Estimate total resources (robots + tools) needed to cover the remaining horizon.
        # Lower is better.
        score = (overhead + R) / wt + (maint * single) / (cont * wt)
        if wt <= R:
            return (0, score, k)
        else:
            # If it doesn't fit, prefer smaller work_time to minimise overrun.
            return (1, wt, score, k)

    valid.sort(key=new_key)

    # Respect the genome's chosen type if it is valid.
    if ctx.gene_type in valid:
        valid.remove(ctx.gene_type)
        valid.insert(0, ctx.gene_type)

    for k in valid:
        actions.append(("new", k))

    return actions

