def rule(ctx):
    actions = []
    # Reuse: urgency (fewer duties left before maintenance) first,
    # then robots that haven't had first maintenance,
    # then balance via budget + 0.15 * hours, then count, then idx.
    if ctx.available:
        def reuse_key(r):
            return (r.duties_left, r.first_maint is not None,
                    r.budget + 0.15 * r.hours, r.count, r.idx)
        actions = [("reuse", r) for r in sorted(ctx.available, key=reuse_key)]

    # New robot type preferences
    valid = []
    for k in range(len(ctx.types)):
        t = ctx.types[k]
        if t is not None and ctx.left[k] > 0:
            valid.append(k)
    if not valid:
        return actions

    def new_key(k):
        t = ctx.types[k]
        wt = t['work_time']
        fits = 0 if wt <= ctx.remaining else 1
        cap = (t['continue_max_work'] // t['single_work_time']) * wt
        overhead = t['out_travel_time'] + t['return_travel_time'] + t['charge_time']
        # Efficiency: overhead per duty hour + maintenance burden per duty hour
        if cap > 0:
            efficiency = overhead / wt + t['maintenance_time'] / cap
        else:
            efficiency = 1e9
        if fits == 0:
            # Fitting: prefer larger capacity, then larger work_time, then efficiency
            return (fits, -cap, -wt, efficiency, k)
        else:
            # Non-fitting: prefer smaller work_time, then efficiency, then larger capacity
            return (fits, wt, efficiency, -cap, k)

    valid.sort(key=new_key)
    # Give genome's preferred type priority if valid
    if ctx.gene_type in valid:
        valid.remove(ctx.gene_type)
        valid.insert(0, ctx.gene_type)

    actions.extend(("new", k) for k in valid)
    return actions

