def rule(ctx):
    # Compute max work_time for endgame cover
    max_wt = 0
    for k in range(len(ctx.types)):
        t = ctx.types[k]
        if t is not None:
            wt = t['work_time']
            if wt > max_wt:
                max_wt = wt

    def reuse_key(r):
        t = ctx.types[r.type]
        # Endgame: prioritize covering remaining horizon
        if ctx.remaining <= max_wt:
            wt = t['work_time']
            if wt >= ctx.remaining:
                # can cover in one shift; prefer smallest wt that covers
                return (0, wt, r.duties_left, r.count, r.hours, r.first_maint is not None, r.idx)
            else:
                # cannot cover; just use urgency/balance
                return (1, r.duties_left, r.count, r.hours, r.first_maint is not None, r.idx)

        # Normal: dynamic threshold between balance and drain
        C = t['continue_max_work'] / max(1, t['single_work_time'])
        thresh = t['maintenance_time'] / max(1, t['work_time'])
        thresh = max(1, min(C, thresh))

        if r.duties_left <= thresh:
            # drain mode: most urgent first
            return (0, r.duties_left, r.count, r.hours, r.first_maint is not None, r.idx)
        else:
            # balance mode: fewer counts first, then fewer hours, then more urgent
            return (1, r.count, r.hours, r.duties_left, r.first_maint is not None, r.idx)

    actions = [("reuse", r) for r in sorted(ctx.available, key=reuse_key)]

    # New robot types: prefer those that fit, then shorter maintenance, then shorter cycle
    valid = []
    for k in range(len(ctx.types)):
        t = ctx.types[k]
        if t is not None and ctx.left[k] > 0:
            valid.append(k)
    if not valid:
        return actions

    def new_key(k):
        t = ctx.types[k]
        wt = t['work_time']
        fits = 0 if wt <= ctx.remaining else 1
        wt_pref = -wt if fits == 0 else wt
        cycle = t['out_travel_time'] + t['work_time'] + t['return_travel_time'] + t['charge_time']
        return (fits, wt_pref, t['maintenance_time'], cycle, -t['continue_max_work'], k)

    valid.sort(key=new_key)
    if ctx.gene_type in valid:
        valid.remove(ctx.gene_type)
        valid.insert(0, ctx.gene_type)

    actions.extend(("new", k) for k in valid)
    return actions

