def rule(ctx):
    available = ctx.available
    actions = []

    # Combined load: average of duty hours and count scaled by average work time.
    total_hours = 0.0
    total_count = 0
    for r in ctx.robots:
        total_hours += r.hours
        total_count += r.count
    if total_count > 0:
        avg_wt = total_hours / total_count
    else:
        avg_wt = 10.0

    def rem_h(r):
        return r.duties_left * ctx.types[r.type]['work_time']

    def load(r):
        return (r.hours + r.count * avg_wt) * 0.5

    def recovery(r):
        t = ctx.types[r.type]
        return t['out_travel_time'] + t['return_travel_time'] + t['charge_time']

    # Adaptive balance weight from capacity slack.
    capacity = ctx.capacity
    slack = capacity - ctx.remaining
    if ctx.remaining > 0:
        alpha = slack / ctx.remaining
        if alpha < 0.0:
            alpha = 0.0
        elif alpha > 1.0:
            alpha = 1.0
    else:
        alpha = 1.0

    def score(r):
        return rem_h(r) + alpha * load(r)

    unmaintained = [r for r in available if r.first_maint is None]
    maintained = [r for r in available if r.first_maint is not None]

    # Sort by score, then shorter recovery, then count, hours, idx.
    unmaintained.sort(key=lambda r: (score(r), recovery(r), r.count, r.hours, r.idx))
    maintained.sort(key=lambda r: (score(r), recovery(r), r.count, r.hours, r.idx))

    for r in unmaintained:
        actions.append(("reuse", r))
    for r in maintained:
        actions.append(("reuse", r))

    # New robot type preference: estimate steady-state robots needed.
    valid = []
    for k in range(len(ctx.types)):
        t = ctx.types[k]
        if t is not None and ctx.left[k] > 0:
            valid.append(k)

    if valid:
        opened_types = set()
        for r in ctx.robots:
            opened_types.add(r.type)

        def new_key(k):
            t = ctx.types[k]
            wt = t['work_time']
            rec = t['out_travel_time'] + t['return_travel_time'] + t['charge_time']
            swt = t['single_work_time']
            cmw = t['continue_max_work']
            mt = t['maintenance_time']
            duties_per_cycle = cmw // swt if swt > 0 else 0
            work_hours = duties_per_cycle * wt
            if work_hours > 0:
                required = (work_hours + duties_per_cycle * rec + mt) / work_hours
            else:
                required = 1e9
            fits = 0 if wt <= ctx.remaining else 1
            existing = 1 if k in opened_types else 0
            if fits == 0:
                wt_pref = -wt
            else:
                wt_pref = wt
            return (fits, -existing, required, mt, -cmw, wt_pref, k)

        valid.sort(key=new_key)
        if ctx.gene_type in valid:
            valid.remove(ctx.gene_type)
            valid.insert(0, ctx.gene_type)

        actions.extend(("new", k) for k in valid)

    return actions

