def rule(ctx):
    R = ctx.remaining
    t = ctx.t
    T = ctx.T
    types = ctx.types

    # ---- available work_times for representability ----
    avail_w = set()
    for k in range(len(types)):
        if types[k] is not None:
            if ctx.left[k] > 0:
                avail_w.add(types[k]['work_time'])
            else:
                for r in ctx.robots:
                    if r.type == k:
                        avail_w.add(types[k]['work_time'])
                        break
    wts = list(avail_w)

    g = 0
    for w in wts:
        g = math.gcd(g, w)

    MC = 240
    dp = [0] * (MC + 1)
    dp[0] = 1
    for i in range(MC + 1):
        if dp[i]:
            for w in wts:
                j = i + w
                if j <= MC:
                    dp[j] = 1

    def is_rep(x):
        if x < 0:
            return False
        if g and x % g:
            return False
        if x > MC:
            return True
        return dp[x] == 1

    def fit_pen(r):
        wt = types[r.type]['work_time']
        if wt > R:
            return 10000
        r2 = R - wt
        if r2 == 0:
            return -1000
        if not is_rep(r2):
            return 1000
        return 0

    # ---- slack-driven load weight ----
    cap = ctx.capacity
    if R > 0:
        slack = cap - R
        alpha = slack / R
        if alpha < 0.0:
            alpha = 0.0
        elif alpha > 2.0:
            alpha = 2.0
    else:
        alpha = 1.0

    def robot_score(r):
        tdict = types[r.type]
        wt = tdict['work_time']
        recov = tdict['out_travel_time'] + tdict['return_travel_time'] + tdict['charge_time']
        cycle = wt + recov
        d = r.duties_left
        maint = tdict['maintenance_time']
        pen = 0
        if d == 1:
            if (t + cycle + maint) < T:
                pen = -maint          # flush early, longer maintenance first
            else:
                pen = 1000            # save as backup
        urg = d * cycle
        return (fit_pen(r) + pen, urg + alpha * r.hours, r.count, r.hours, r.idx)

    def robot_score_bal(r):
        tdict = types[r.type]
        wt = tdict['work_time']
        return (fit_pen(r), alpha * r.hours + r.duties_left * wt, r.count, r.hours, r.idx)

    un = [r for r in ctx.available if r.first_maint is None]
    mt = [r for r in ctx.available if r.first_maint is not None]

    u_flush = sorted(un, key=robot_score)
    u_bal = sorted(un, key=robot_score_bal)
    m_flush = sorted(mt, key=robot_score)
    m_bal = sorted(mt, key=robot_score_bal)

    def interleave(a, b):
        out = []
        seen = set()
        i = j = 0
        la, lb = len(a), len(b)
        for _ in range(la + lb):
            if i < la:
                r = a[i]; i += 1
                if r.idx not in seen:
                    seen.add(r.idx); out.append(r)
            if j < lb:
                r = b[j]; j += 1
                if r.idx not in seen:
                    seen.add(r.idx); out.append(r)
        return out

    actions = []
    for r in interleave(u_flush, u_bal):
        actions.append(("reuse", r))
    for r in interleave(m_flush, m_bal):
        actions.append(("reuse", r))

    # ---- new-robot type preference ----
    valid = []
    for k in range(len(types)):
        if types[k] is not None and ctx.left[k] > 0:
            valid.append(k)

    if valid:
        opened = set(r.type for r in ctx.robots)
        def new_key(k):
            tdict = types[k]
            wt = tdict['work_time']
            swt = tdict['single_work_time']
            cmw = tdict['continue_max_work']
            mtm = tdict['maintenance_time']
            oh = tdict['out_travel_time'] + tdict['return_travel_time'] + tdict['charge_time']
            d = cmw // swt if swt > 0 else 0
            if d > 0:
                wh = d * wt
                required = (wh + d * oh + mtm) / wh
            else:
                required = 1e9
            if wt > R:
                bad = 2
                exact = 0
                wpref = wt
            else:
                r2 = R - wt
                if r2 == 0:
                    bad = 0; exact = 1
                elif is_rep(r2):
                    bad = 0; exact = 0
                else:
                    bad = 1; exact = 0
                wpref = -wt
            existing = 1 if k in opened else 0
            return (bad, -exact, -existing, required, mtm, -cmw, wpref, k)
        valid.sort(key=new_key)
        if ctx.gene_type in valid:
            valid.remove(ctx.gene_type)
            valid.insert(0, ctx.gene_type)
        for k in valid:
            actions.append(("new", k))

    return actions

r52.src:
def rule(ctx):
    R = ctx.remaining

    # ---- representable remainders: gcd + small DP over work-times ----
    work_times = []
    for k in range(len(ctx.types)):
        t = ctx.types[k]
        if t is not None:
            work_times.append(t['work_time'])
    work_times = list(set(work_times))

    g = 0
    for wt in work_times:
        g = math.gcd(g, wt)

    max_check = 200
    dp = [False] * (max_check + 1)
    dp[0] = True
    for i in range(max_check + 1):
        if dp[i]:
            for wt in work_times:
                j = i + wt
                if j <= max_check:
                    dp[j] = True

    def is_rep(x):
        if x < 0:
            return False
        if g > 0 and x % g != 0:
            return False
        if x > max_check:
            return True
        return dp[x]

    # ---- load-balancing statistics ----
    total_hours = 0.0
    total_count = 0
    for r in ctx.robots:
        total_hours += r.hours
        total_count += r.count
    avg_wt = total_hours / total_count if total_count > 0 else 10.0

    capacity = ctx.capacity
    slack = capacity - R
    if R > 0:
        alpha = slack / R
        if alpha < 0.0:
            alpha = 0.0
        elif alpha > 1.0:
            alpha = 1.0
    else:
        alpha = 1.0

    def load(r):
        return r.hours + r.count * avg_wt

    def urgency(r):
        t = ctx.types[r.type]
        cycle = t['work_time'] + t['out_travel_time'] + t['return_travel_time'] + t['charge_time']
        return r.duties_left * cycle

    def recovery(r):
        t = ctx.types[r.type]
        return t['out_travel_time'] + t['return_travel_time'] + t['charge_time']

    def rem_h(r):
        return r.duties_left * ctx.types[r.type]['work_time']

    def fit_penalty(r):
        wt = ctx.types[r.type]['work_time']
        if wt > R:
            return 10000
        R2 = R - wt
        if R2 == 0:
            return -1000
        if not is_rep(R2):
            return 1000
        return 0

    def comb_score(r):
        return (fit_penalty(r), urgency(r) + alpha * load(r))

    def bal_score(r):
        return (fit_penalty(r), load(r))

    def rule1_score(r):
        return (fit_penalty(r), rem_h(r) + alpha * r.hours)

    avail = ctx.available
    unmaintained = [r for r in avail if r.first_maint is None]
    maintained = [r for r in avail if r.first_maint is not None]

    def split_feasible(group):
        feas = []
        infeas = []
        for r in group:
            if fit_penalty(r) < 1000:
                feas.append(r)
            else:
                infeas.append(r)
        return feas, infeas

    u_feas, u_infeas = split_feasible(unmaintained)
    m_feas, m_infeas = split_feasible(maintained)

    def order_lists(feas):
        comb = sorted(feas, key=lambda r: (comb_score(r), recovery(r), r.count, r.hours, r.idx))
        bal = sorted(feas, key=lambda r: (bal_score(r), recovery(r), r.count, r.hours, r.idx))
        rule1 = sorted(feas, key=lambda r: (rule1_score(r), recovery(r), r.count, r.hours, r.idx))
        return comb, bal, rule1

    u_comb, u_bal, u_rule1 = order_lists(u_feas)
    m_comb, m_bal, m_rule1 = order_lists(m_feas)

    def interleave(lists):
        out = []
        seen = set()
        idx = [0] * len(lists)
        unique = set()
        for l in lists:
            for r in l:
                unique.add(r.idx)
        unique_count = len(unique)
        sum_len = sum(len(l) for l in lists)
        for _ in range(sum_len * len(lists) + 1):
            if len(out) >= unique_count:
                break
            for i in range(len(lists)):
                if idx[i] < len(lists[i]):
                    r = lists[i][idx[i]]
                    idx[i] += 1
                    if r.idx not in seen:
                        seen.add(r.idx)
                        out.append(r)
                        if len(out) >= unique_count:
                            break
        return out

    actions = []
    for r in interleave([u_comb, u_bal, u_rule1]):
        actions.append(("reuse", r))
    for r in interleave([m_comb, m_bal, m_rule1]):
        actions.append(("reuse", r))

    u_infeas.sort(key=lambda r: (comb_score(r), recovery(r), r.count, r.hours, r.idx))
    m_infeas.sort(key=lambda r: (comb_score(r), recovery(r), r.count, r.hours, r.idx))
    for r in u_infeas:
        actions.append(("reuse", r))
    for r in m_infeas:
        actions.append(("reuse", r))

    valid = []
    for k in range(len(ctx.types)):
        t = ctx.types[k]
        if t is not None and ctx.left[k] > 0:
            valid.append(k)

    if valid:
        opened_types = set()
        for r in ctx.robots:
            opened_types.add(r.type)

        def new_key(k):
            t = ctx.types[k]
            wt = t['work_time']
            swt = t['single_work_time']
            cmw = t['continue_max_work']
            mt = t['maintenance_time']
            out_t = t['out_travel_time']
            ret_t = t['return_travel_time']
            ch_t = t['charge_time']

            duties_per_cycle = cmw // swt if swt > 0 else 0
            work_hours = duties_per_cycle * wt
            if work_hours > 0:
                required = (work_hours + duties_per_cycle * (out_t + ret_t + ch_t) + mt) / work_hours
            else:
                required = 1e9

            if wt > R:
                bad_fit = 2
                exact = 0
                wt_pref = wt
            else:
                R2 = R - wt
                if R2 == 0:
                    exact = 1
                    bad_fit = 0
                elif not is_rep(R2):
                    exact = 0
                    bad_fit = 1
                else:
                    exact = 0
                    bad_fit = 0
                wt_pref = -wt

            existing = 1 if k in opened_types else 0
            return (bad_fit, -exact, -existing, required, mt, -cmw, wt_pref, k)

        valid.sort(key=new_key)
        if ctx.gene_type in valid:
            valid.remove(ctx.gene_type)
            valid.insert(0, ctx.gene_type)

        for k in valid:
            actions.append(("new", k))

    return actions
